import pathlib,subprocess,time,json,statistics,fcntl
D=pathlib.Path('/tmp/sirkit_rh_next_strategy_20261023'); variants=['baseline','probe4_ilp_allinline']
locks=[open('/tmp/sirkit_performance_cpu14.lock','w'),open('/tmp/atcoder_full_performance_20261018/benchmark.lock','w')]
for l in locks:fcntl.flock(l,fcntl.LOCK_EX)
for compiler in ['/usr/bin/g++','clang++']:
 c='gcc' if compiler=='/usr/bin/g++' else 'clang'
 for op in [0,1]:
  for v in variants:
   subprocess.run(['taskset','-c','6',compiler,*(['--gcc-install-dir=/opt/atcoder/gcc/lib/gcc/x86_64-pc-linux-gnu/15.3.0'] if c=='clang' else []),'-O2','-std=c++23','-march=native',f'-DOP={op}',f'-DSOURCE="{D}/{v}.hpp"',str(D/'api.cpp'),'-o',str(D/f'api_{c}_{op}_{v}')],check=True)
res={}
for c in ['gcc','clang']:
 for op in [0,1]:
  for n in [131072]:
   for pattern in [0,8,9]:
    q=500000 if n==32 else 131072
    vals={v:[] for v in variants};checks={}
    for rep in range(9):
     order=variants[rep%len(variants):]+variants[:rep%len(variants)]
     for v in order:
      out=subprocess.check_output(['taskset','-c','14',str(D/f'api_{c}_{op}_{v}'),str(n),str(pattern),str(q)]).decode().split();vals[v].append(int(out[0]));checks[v]=int(out[1])
    assert len(set(checks.values()))==1,checks
    key=f'{c}_{op}_{n}_{pattern}';res[key]={'ns':vals,'checks':checks,'ratios':{v:statistics.median(vals[v])/statistics.median(vals['baseline']) for v in variants}}
    print(key,{v:round(x,3)for v,x in res[key]['ratios'].items()},flush=True)
    (D/'allinline_api.json').write_text(json.dumps(res,indent=2))

